import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.CS-cBh1g.js";const n="/Mayhem/img/suite/logs.jpg",m=JSON.parse('{"title":"Logs","description":"","frontmatter":{},"headers":[],"relativePath":"suite/logs.md","filePath":"suite/logs.md"}'),s={name:"suite/logs.md"};function i(d,e,l,g,p,h){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="logs" tabindex="-1">Logs <a class="header-anchor" href="#logs" aria-label="Permalink to &quot;Logs&quot;">​</a></h1><p>Every recording is checked for red flags and power problems as soon as it arrives.</p><p><img src="'+n+'" alt="The Logs workspace"></p><h2 id="the-library" tabindex="-1">The library <a class="header-anchor" href="#the-library" aria-label="Permalink to &quot;The library&quot;">​</a></h2><p>Import a <code>.wpilog</code> with the upload button, or let <a href="/Mayhem/suite/robot#log-collection">log collection</a> bring them in. Recordings are stored on this computer. Filter the list by name; right-click a recording to open its report, open it in AdvantageScope, export the original, copy its name or path, archive it, or delete it.</p><p><strong>Team cloud</strong> (desktop) lists recordings your teammates uploaded to the team site. Download one into your library with its cloud button. It needs a device token; <strong>Add token</strong> takes you to <a href="/Mayhem/suite/robot#team-upload">Team upload</a>.</p><p>Supported: WPILOG 1.0 scalars, numeric and boolean arrays, and common WPILib structs. Unknown types are reported, not dropped silently. Limit: 250 MB and two million samples per file.</p><h2 id="the-report" tabindex="-1">The report <a class="header-anchor" href="#the-report" aria-label="Permalink to &quot;The report&quot;">​</a></h2><p>The header has the verdict, findings linked to their times, and buttons to export the original or the report, open it in AdvantageScope, archive or delete. Click a finding to move the shared cursor there.</p><table tabindex="0"><thead><tr><th>Tab</th><th>Use</th></tr></thead><tbody><tr><td><strong>Health</strong></td><td>Findings, plus coverage and limits: which signals the findings could and couldn&#39;t use.</td></tr><tr><td><strong>Power</strong></td><td>Lowest battery, the voltage graph against the 6.8 V brownout line, energy, and the biggest current draws. Estimated currents are labeled.</td></tr><tr><td><strong>Signals</strong></td><td>Search channels and plot them at the shared cursor.</td></tr><tr><td><strong>Field</strong></td><td>Replay recognized pose data at the same cursor.</td></tr></tbody></table><h3 id="signal-mapping" tabindex="-1">Signal mapping <a class="header-anchor" href="#signal-mapping" aria-label="Permalink to &quot;Signal mapping&quot;">​</a></h3><p>Mayhem finds voltage and current signals by name. If it guesses wrong, set them under <strong>Power → Signal mapping</strong>, one per device, or open <strong>Agent / custom signal mapping</strong>: <strong>Download signal catalog</strong>, have an agent write the mapping, paste it, and <strong>Apply mapping</strong>. <strong>Reset to automatic detection</strong> undoes it. Mappings are saved per recording and match the team site&#39;s Logs page.</p><p>Findings depend on which signals are in the log. Check each one against its evidence.</p>',13)])])}const u=t(s,[["render",i]]);export{m as __pageData,u as default};
